Web Application & Mobile Client Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(web_mobile_client_gateway, "Web Application & Mobile Client Gateway") {
    Component(Web_and_Mobile_Client_Interface, "Web and Mobile Client Interface", "React / React Native", "Cross-platform frontend supporting multilingual UI and accessibility for patients, clinicians, pharmacists, auditors, and administrators.")
    Component(Client_Routing___Auth_Interceptor, "Client Routing & Auth Interceptor", "Envoy Proxy", "Handles edge routing, TLS termination, WAF, rate limiting, and circuit breaking.")
    Component(Offline_Resilience_Cache, "Offline Resilience Cache", "Redux Persist / SQLCipher", "Provides client-side storage encryption for PHI protection on mobile devices and offline resilience.")
}

Rel(Web_and_Mobile_Client_Interface, Client_Routing___Auth_Interceptor, "Routes client requests and handles authentication", "HTTPS / JSON")
Rel(Client_Routing___Auth_Interceptor, Offline_Resilience_Cache, "Persists local state and encrypted PHI", "Local Storage")

@enduml

WebRTC Video Session Orchestrator.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(Web_RTC_Video_Session_Orchestrator, "WebRTC Video Session Orchestrator") {
    Component(Signaling_Controller, "Signaling Controller", "Node.js / WebSockets", "Manages real-time session signaling, coordination, and asynchronous audit logging via gRPC.")
    Component(Adaptive_Bitrate_Manager, "Adaptive Bitrate Manager", "Go", "Monitors network conditions and dynamically adjusts media streams for low-bandwidth resilience.")
    Component(TURN_SFU_Proxy_Controller, "TURN/SFU Proxy Controller", "C++ / Pion-based", "Handles media relay and routing for real-time video/audio sessions using blind-relay enforcement.")
}

Rel(Signaling_Controller, Adaptive_Bitrate_Manager, "Communicates via internal channels to manage stream bitrates", "Internal channels")
Rel(TURN_SFU_Proxy_Controller, Signaling_Controller, "Coordinates media session paths and signaling states", "Internal")

@enduml

Database and Storage.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Database and Storage container

Container_Boundary(database_and_storage, "Database and Storage") {
    Component(PostgreSQL Database, "PostgreSQL Database", "Google Cloud SQL PostgreSQL (Enterprise Plus), Row-Level Security, TLS 1.3", "Persists patient data, operational records, and audit logs with region-locked data residency.")
    Component(WORM Storage, "WORM Storage", "Google Cloud Storage, Regional WORM Bucket Lock, CMEK via Cloud KMS", "Stores immutable audit logs and compliance records to satisfy EU MDR traceability and accountability.")
}

Rel(PostgreSQL Database, WORM Storage, "Synchronizes or archives operational audit data for compliance retention.")

@enduml

Service Mesh.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(Service_Mesh, "Service Mesh") {
    Component(Istio_Service_Mesh, "Istio Service Mesh", "Istio", "Manages service-to-service communication, enforcing strict mTLS and routing policies.")
    Component(Envoy_Proxy, "Envoy Proxy", "Envoy proxy", "Acts as the data plane proxy enforcing security and consent-driven access control.")
}

Rel(Istio_Service_Mesh, Envoy_Proxy, "Pushes routing and security policies", "gRPC")

@enduml
